mapper.select:
select
c.content
from litemall_comment c

    inner join litemall_goods g on g.id = c.value_id

where c.type = 0
and c.deleted = 0
and c.content is not null
and c.content != ''

    and c.value_id = #{goodsId}


    and (
        g.category_id = #{categoryId}
        or g.category_id in (
            select id from litemall_category where pid = #{categoryId}
        )
    )

order by c.add_time desc

    limit #{limit}
